648	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
649	    //    2D weights (INTEGRATION-OPTSTAGES §3). For EACH 2D matrix (kVitMuon2D) all
650	    //    CTAs cooperate: buf=μ·buf+g (buf is the PERSISTENT m-slice — momentum state,
651	    //    NOT transient), ‖buf‖_F via per-CTA partials → inv_norm, X=buf·inv_norm,
652	    //    then ns_steps × { A=XXᵀ → AX=A·X → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap },
653	    //    then the canonical muon_update_step apply (decay·p + neg_lr_scale·orth). The
654	    //    1D / non-2D weights (cls_token, biases, LN γ/β) take the AdamW tail in P3.
655	    //    The elementwise bodies CALL muon.h (muon_momentum_normalize_step via the
656	    //    phaseA buf body, muon_ns_combine_step, muon_update_step); the matmuls are the
657	    //    cited new device code (the eager path delegates to torch::mm/cuBLAS). Guarded
658	    //    so every other opt is byte-identical (no extra barriers / work).
659	    if constexpr (Opt == OptId::Muon) {
660	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
661	        PrecomputeWorkspace pw{};
662	        pw.muon_X            = muon_base;
663	        pw.muon_AX           = pw.muon_X   + kVitMuonMaxNumel;
664	        pw.muon_AAX          = pw.muon_AX  + kVitMuonMaxNumel;
665	        pw.muon_orth         = pw.muon_AAX + kVitMuonMaxNumel;
666	        pw.muon_A            = pw.muon_orth + kVitMuonMaxNumel;
667	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows;
668	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
669	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
670	        const int   ns_steps = 5;                 // bindings.cpp default
671	        for (int mi = 0; mi < vittc::kVitNumMuon2D; ++mi) {
672	            const vittc::VitMuon2D M = vittc::kVitMuon2D[mi];
673	            const int rows = M.rows, cols = M.cols;
674	            const int64_t numel = (int64_t)rows * cols;
675	            const int64_t off   = (int64_t)kVitOffsets[M.tidx];
676	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
677	            pw.muon_buf = st.exp_avg + off;
678	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
679	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
680	            bar.sync();
681	            muon_norm_reduce_phaseB(ctx, pw);
682	            bar.sync();
683	            muon_scale_X(numel, pw);
684	            bar.sync();
685	            // NS iterations. After each combine, orth holds the new iterate; swap so
686	            // the next iteration reads it as X. ns_steps swaps → final result is in
687	            // muon_X iff ns_steps even else muon_orth (we track the parity below).
688	            for (int s = 0; s < ns_steps; ++s) {
689	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
690	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
691	                bar.sync();
692	                // AX = A X   (M=rows,N=cols,K=rows).
693	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
694	                bar.sync();
695	                // AAX = A (AX) (M=rows,N=cols,K=rows).
696	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
697	                bar.sync();
698	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
699	                bar.sync();
700	                // swap X <-> orth (next iter reads X; final result tracked by parity).
701	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
702	            }
703	            // After ns_steps swaps the final orthogonalized matrix is in muon_X (the
704	            // last combine wrote muon_orth, then we swapped → muon_X). Apply Muon:
705	            //   p = decay_factor·p + neg_lr_scale·orth   (muon.h:63-73)
706	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
707	            const float neg_lr_scale = -lr * scale;
708	            const float decay_factor = 1.0f - lr * st.wd;
709	            float* __restrict__ p = params + off;
710	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
711	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
712	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
713	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
714	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
715	        }
716	    }
