725	        TaskQueue q = ctx.queue();
726	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
727	             t = q.next_block(&task_slot)) {
728	            const int n = kVitSizes[t];
729	            const int64_t off = (int64_t)kVitOffsets[t];
730	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
731	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
732	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
733	            if constexpr (Opt == OptId::Muon) {
734	                if (vittc::vit_is_muon_2d(t)) continue;
735	            }
736	            FusedOptState ts = vit_rebase_state<Opt>(st, off);
737	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
738	            //     t == the tensor's flat named_parameters() layer index (the
739	            //     work-steal task id maps 1:1 to kVitOffsets order == the eager
740	            //     enumeration order — cls_token is t=0). bc1 must be rebased TOO
741	            //     (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager; bc2 stays global.
742	            if constexpr (Opt == OptId::GrokAdamW) {
743	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
744	                ts.beta1 = b1;
745	                ts.bc1   = 1.0f - powf(b1, (float)step);
746	            }
747	            float* __restrict__ p = params + off;
748	            const float* __restrict__ gg = grad + off;
749	            if constexpr (Opt == OptId::Muon) {
750	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:115-125 routes
751	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
752	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
753	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
754	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
755	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
756	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
757	                // bc1/bc2 are device-computed here from aux_beta^step (kept out of the
758	                // mirror to shrink the host ABI surface; fp32 powf, tol 2e-3 is ample).
759	                // apply_optimizer<Muon> would deref st.orth (NS dir, only valid for 2D),
760	                // so route directly to adamw_step with the aux hyperparameters.
761	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
762	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
763	                for (int i = threadIdx.x; i < n; i += blockDim.x)
764	                    algo::adamw_step<float, float>(
765	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
766	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
767	                        a_bc1, a_bc2, (int64_t)i);
768	            } else {
769	                for (int i = threadIdx.x; i < n; i += blockDim.x)
770	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
771	            }
772	        }
773	    }
774	#ifdef SG_VIT_PROFILE
775	    if (threadIdx.x == 0) { unsigned long long _p3b = clock64(); atomicMax(&g_vit_prof_max[5], _p3b - _p3a); }
