365	template <OptId Opt>
366	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
367	fused_decoder_megakernel_tc(PersistentContext ctx,
368	                            float* __restrict__ params,
369	                            DecoderTokenCtx tok,
370	                            float* __restrict__ grad,
371	                            float lr, int step, FusedOptState st) {
372	    __shared__ DecTcSmem sm;
373	    GridBarrier bar = ctx.barrier();
374	    const int cta = blockIdx.x;
375	    const int nCTA = (int)ctx.n_ctas;
376	    const int B = tok.B;
377	    const int T = B * dec::kSeq;
378	
379	    // Workspace partition.
380	    float* ws = tok.workspace;
381	    const int64_t acts_f = dec_tc_acts_floats(T, B);
382	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
383	    float* scratch_base = ws + acts_f;
384	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
385	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
386	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
387	    float* loss_out   = loss_part + nCTA;
388	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
389	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
390	    float* dw_part    = loss_out + 1;
391	    const int kDwG    = dectc::kDecDwSplitK;
392	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
393	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
394	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
395	
396	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
397	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
398	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
399	
400	    DecWeights w = dec_bind(params);
401	
402	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
403	    //    written-once → no pre-zero). ──
404	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
405	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
406	    bar.sync();   // B0
407	
408	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
409	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
410	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
411	    const int nrows_tile = dectc::kTileM;
412	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
413	    float nll_acc = 0.0f;
414	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
415	        const int g0 = ti * nrows_tile;
416	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
417	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
418	                                              sm.sA, sm.sB, sm.red);
419	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
420	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
421	        if (threadIdx.x == 0) nll_acc += nll;
422	        __syncthreads();
423	    }
424	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
425	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
426	
427	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
428	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
429	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the

566	        bar.sync();   // B2.6b: d visible to every CTA before the apply
567	        st.d_factor = pw.prodigy_d[0];              // the reduced d the tail reads
568	    }
569	
570	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
571	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
572	    st.lr = lr;
573	    {
574	        __shared__ int task_slot;
575	        TaskQueue q = ctx.queue();
576	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
577	             t = q.next_block(&task_slot)) {
578	            const int n = kDecSizes[t];
579	            const int64_t off = (int64_t)kDecOffsets[t];
580	            FusedOptState ts = rebase_state<Opt>(st, off);
581	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
582	            //     t == the tensor's flat named_parameters() layer index (the
583	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
584	            //     enumeration order, so t IS the eager layer index). bc1 must be
585	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
586	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
587	            if constexpr (Opt == OptId::GrokAdamW) {
588	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
589	                ts.beta1 = b1;
590	                ts.bc1   = 1.0f - powf(b1, (float)step);
591	            }
592	            float* __restrict__ p = params + off;
593	            const float* __restrict__ gg = grad + off;
594	            for (int i = threadIdx.x; i < n; i += blockDim.x)
595	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
596	        }
597	    }
