600	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
601	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
602	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
603	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
604	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
605	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
606	// nCTA (the dW/embedding owner maps are functions of nCTA).
607	template <OptId Opt>
608	cudaError_t launch_fused_decoder_megakernel_tc(
609	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
610	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
611	        int ncta_cap = 0) {
612	    int dev = 0;
613	    cudaError_t err = cudaGetDevice(&dev);
614	    if (err != cudaSuccess) return err;
615	    int n_sms = 0;
616	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
617	    if (err != cudaSuccess) return err;
618	
619	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
620	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
621	    // can't place one block/SM, REFUSE (the grid barrier would hang).
622	    int occ = 0;
623	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
624	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
625	        /*dynamicSMemBytes=*/0);
626	    if (err != cudaSuccess) return err;
627	    if (occ < 1) return cudaErrorLaunchOutOfResources;
628	
629	    unsigned launch_ctas = (unsigned)n_sms;
630	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
631	    ctx.n_ctas = launch_ctas;
632	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
633	    // AND it guarantees full token tiles for the projections). NO G-divisibility
634	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
635	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
636	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
637	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
638	
639	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
640	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
641	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
642	
643	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
644	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
645	        ctx, params, tok, grad, lr, step, st);
646	    return cudaGetLastError();
647	}
